def is_balanced(s):
    depth = 0
    for char in s:
        if char == "(":
            depth += 1
        elif char == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

The counter tracks unmatched opening parentheses. The string is unbalanced if a closing parenthesis appears without a match or if any opening parentheses remain at the end.

def balanced(s):
    stack = []
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

```python
def balanced_parentheses(text):
    balance = 0
    for ch in text:
        if ch == "(":
            balance += 1
        else:  # input contains only '(' and ')'
            balance -= 1
        if balance < 0:
            return False
    return balance == 0
```
The balance must never become negative, and it must return to zero at the end.

from collections import defaultdict

def group_anagrams(words):
    groups = defaultdict(list)
    for word in words:
        key = "".join(sorted(word.lower()))
        groups[key].append(word)
    return list(groups.values())

The grouping key is the word converted to lowercase with its letters sorted alphabetically. Anagrams contain the same letters, so they produce the same key; for example, "Listen" and "silent" both become "eilnst".

def group_anagrams(words):
    groups = {}
    for w in words:
        key = ''.join(sorted(w.lower()))
        groups.setdefault(key, []).append(w)
    return list(groups.values())
# The key is the sorted lowercase letters of the word.

