def merge_sorted(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for d in range(3, math.isqrt(n) + 1, 2):
        if n % d == 0:
            return False
    return True

The function checks divisors only up to the square root of n, because any factor larger than the square root would pair with a smaller factor already checked. It also skips even divisors after checking 2.

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
# We only check up to sqrt(n) because any factor larger than sqrt(n) pairs with one smaller.

```python
def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True
```
It is enough to test possible divisors only up to √n, because if n has a factor larger than √n, the matching factor must be smaller than √n. After checking 2, the function tests only odd divisors.

def length_of_longest_substring(s):
    last_seen = {}
    start = 0
    best = 0
    for end, char in enumerate(s):
        if char in last_seen and last_seen[char] >= start:
            start = last_seen[char] + 1
        last_seen[char] = end
        best = max(best, end - start + 1)
    return best

The sliding window keeps a substring with no repeated characters. The right edge moves forward one character at a time. If a character repeats inside the window, the left edge moves just past its previous position. Each character is processed once, so the time complexity is O(n).

def longest_unique_substring(s):
    seen = {}
    start = 0
    max_len = 0
    for i, c in enumerate(s):
        if c in seen and seen[c] >= start:
            start = seen[c] + 1
        seen[c] = i
        max_len = max(max_len, i - start + 1)
    return max_len
# Sliding window: expand right, move left past duplicates. Time O(n).

```python
def longest_unique_substring_length(text):
    last_seen = {}
    left = 0
    best = 0

    for right, ch in enumerate(text):
        if ch in last_seen and last_seen[ch] >= left:
            left = last_seen[ch] + 1
        last_seen[ch] = right
        best = max(best, right - left + 1)

    return best
```
The sliding window `[left, right]` always contains no repeated character. When a repeated character appears inside the current window, `left` jumps past its previous position. Each character is processed once, so the time complexity is O(n), with O(k) extra space for the character map.

from collections import deque

def shortest_path(graph, start, goal):
    queue = deque([start])
    parent = {start: None}
    while queue:
        vertex = queue.popleft()
        if vertex == goal:
            path = []
            while vertex is not None:
                path.append(vertex)
                vertex = parent[vertex]
            return path[::-1]
        for neighbor in graph.get(vertex, []):
            if neighbor not in parent:
                parent[neighbor] = vertex
                queue.append(neighbor)
    return None

BFS explores vertices in order of distance from the start, so the first time it reaches the goal, the reconstructed path is a shortest path. It returns None if the goal is unreachable.

from collections import deque

def bfs_path(graph, start, end):
    if start == end:
        return [start]
    queue = deque([[start]])
    visited = {start}
    while queue:
        path = queue.popleft()
        node = path[-1]
        for nxt in graph.get(node, []):
            if nxt == end:
                return path + [nxt]
            if nxt not in visited:
                visited.add(nxt)
                queue.append(path + [nxt])
    return None

```python
from collections import deque

def bfs_shortest_path(graph, start, goal):
    if start == goal:
        return [start]

    queue = deque([[start]])
    visited = {start}

    while queue:
        path = queue.popleft()
        node = path[-1]
        for neighbor in graph.get(node, []):
            if neighbor in visited:
                continue
            new_path = path + [neighbor]
            if neighbor == goal:
                return new_path
            visited.add(neighbor)
            queue.append(new_path)

    return None
```
Breadth-first search explores vertices by increasing path length, so the first path found to the goal is a shortest path in an unweighted graph.

